from robot.api import SuiteVisitor
import os
import re
import logging



class AddIdForTCs(SuiteVisitor):
    ROBOT_LISTENER_API_VERSION = 3
    _soothing_message = "Note: test execution is NOT AFFECTED by this error."

    def __init__(self):
        self.cm_execution_id = os.getenv("CM_EXECUTION_ID")
        if self.cm_execution_id is None:
            logging.warning(
                "CM_EXECUTION_ID variable was not found, test id tag will NOT be added."
                + self._soothing_message
            )
            self.visit_test = False

    def visit_test(self, test):
        testcase_id = re.findall(
            r't(\d+)$',  # Find exactly one Robot Test Case ID
            test.id)[0]
        test.tags.add("ute:id:{}-{}".format(self.cm_execution_id, testcase_id))
